import {createCapsule, verifyCapsule, parseCapsuleJSON, bytesToBase64, base64ToBytes, LIMITS} from './engine.js';
import {encryptCapsule, decryptCapsule, isEncrypted} from './crypto.js';
const $ = s=>document.querySelector(s);
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtBytes = n=> n<1024 ? `${n} Б` : n<1048576 ? `${(n/1024).toFixed(1)} КБ` : `${(n/1048576).toFixed(2)} МБ`;
const labels={home:'Обзор',create:'Создать капсулу',verify:'Проверить капсулу',vault:'Локальное хранилище',guide:'Как это работает'};
let draft={title:'',description:'',owner:'',license:'',files:[],checks:[]};let current=null,report=null,pendingEncrypted=null,busy=false,dbPromise=null,toastTimer;
const app=$('#app');
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500)}
function showError(message,target='#form-error'){const el=$(target);if(el){el.textContent=message;el.hidden=false;el.scrollIntoView({block:'nearest',behavior:'smooth'})}else toast(message)}
function failText(e){return e?.message||'Не удалось выполнить действие. Проверьте данные и попробуйте снова.'}
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('continuum-vault-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('capsules',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{dbPromise=null;reject(Error('Локальное хранилище недоступно. Скачайте капсулу отдельным файлом.'))}});return dbPromise}
async function vault(action,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('capsules',action==='list'?'readonly':'readwrite'),store=tx.objectStore('capsules');let req;if(action==='list')req=store.getAll();else if(action==='save')req=store.put(value);else req=store.delete(value);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(Error('Не удалось сохранить изменения в браузере. Возможно, недостаточно места.'))})}
async function countVault(){try{$('#vault-count').textContent=(await vault('list')).length}catch{$('#vault-count').textContent='—'}}
function pageTitle(title,sub,action=''){return `<div class="page-title"><div><div class="eyebrow">CONTINUUM / ${esc(labels[route()])}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function route(){const r=location.hash.slice(1);return labels[r]?r:'home'}
function setRoute(r){if(route()===r)render();else location.hash=r}
function setBusy(value){busy=value;document.body.classList.toggle('busy',value);app.setAttribute('aria-busy',String(value));app.querySelectorAll('button').forEach(b=>b.disabled=value);if(!value&&app.dataset.route!==route())render()}
function download(data,name,type='application/json'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function demo(){draft={title:'Передача каталога мастерской',description:'Демонстрационный пакет: список изделий, условия передачи и конфигурация. Все данные вымышлены. Проверяется структура файлов, а не запуск производства.',owner:'Демо-мастерская',license:'Демонстрационные материалы: разрешено изучение и повторное использование.',files:[{name:'handover.json',mime:'application/json',dataBase64:bytesToBase64(new TextEncoder().encode(JSON.stringify({version:1,status:{ready:true},contact:'demo@example.invalid'},null,2)))},{name:'catalog.csv',mime:'text/csv',dataBase64:bytesToBase64(new TextEncoder().encode('sku,name,quantity\nDEMO-01,Керамическая чашка,12\nDEMO-02,Тарелка,8\n'))},{name:'README.txt',mime:'text/plain',dataBase64:bytesToBase64(new TextEncoder().encode('Демонстрационный пакет Continuum.\nПроверьте подпись и критерии, затем сверьте fingerprint с отправителем.\nЭто не документ о передаче исключительных прав.\n'))}],checks:[{type:'json',file:'handover.json',path:'status.ready',expected:'true'},{type:'csv',file:'catalog.csv',columns:'sku,name,quantity'}]};current=null;report=null;setRoute('create');toast('Демо-набор добавлен. Его можно изменить перед созданием.')}
function home(){app.innerHTML=pageTitle('Ценность, которую можно передать.','Упакуйте важные файлы, зафиксируйте условия и дайте получателю проверить пакет самостоятельно.',`<a class="button" href="#guide">О продукте <span>↗</span></a>`)+`
<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="online-dot"></span> ПЕРЕНОСИМЫЙ ЦИФРОВОЙ ПАКЕТ</div><h2>Сохраните больше,<br>чем просто файлы.</h2><p>Капсула объединяет содержимое, подпись и явные критерии проверки. Для передачи проекта, данных или рабочего процесса.</p><div class="actions"><a class="button lime" href="#create">Создать капсулу <span>↗</span></a><button class="button ghost" id="demo-home">Попробовать пример →</button></div></div><div class="capsule-visual" aria-label="Иллюстрация структуры капсулы"><div class="orbit"></div><div class="mock-capsule"><div class="cap-head"><span>CONTINUUM CAPSULE</span><span>↗</span></div><div class="cap-icon">◈</div><h3>Проект. Данные. Контекст.</h3><small>В одном переносимом пакете</small><div class="cap-row first"><span>Содержимое</span><span>SHA-256 ✓</span></div><div class="cap-row"><span>Подпись пакета</span><span>ECDSA P-256 ✓</span></div><div class="cap-row"><span>Ваши критерии</span><span>Проверяемы ✓</span></div></div><div class="seal">✓ Проверка без доверия к серверу</div></div></section>
<div class="stats"><div class="stat"><div class="stat-symbol">↗</div><div><strong>Один файл</strong><p>Пакет можно скачать и передать</p></div></div><div class="stat"><div class="stat-symbol">⌘</div><div><strong>На устройстве</strong><p>Содержимое не отправляется на сервер</p></div></div><div class="stat"><div class="stat-symbol">◈</div><div><strong>Явные критерии</strong><p>Состав, JSON-поля и CSV-колонки</p></div></div></div>
<div class="section-head"><h2>От набора файлов — к проверяемой передаче</h2><small>ТРИ ПРОСТЫХ ШАГА</small></div><div class="features"><article class="feature"><div class="num">01 / СОБРАТЬ</div><h3>Добавьте содержимое и контекст</h3><p>Файлы, описание владельца и условия, на которых вы передаёте материалы.</p></article><article class="feature"><div class="num">02 / ЗАФИКСИРОВАТЬ</div><h3>Определите, что проверять</h3><p>Задайте наличие файлов, значения полей JSON и обязательные колонки CSV.</p></article><article class="feature"><div class="num">03 / ПЕРЕДАТЬ</div><h3>Получатель проверит сам</h3><p>Подпись, контрольные суммы и критерии повторно проверяются в браузере.</p></article></div><div class="note">Подпись подтверждает неизменность пакета. Личность, права, полнота передачи и работоспособность целого бизнеса требуют отдельной проверки. Рыночная цена капсулы не установлена.</div>`;$('#demo-home').onclick=demo}
function createPage(){app.innerHTML=pageTitle('Создать капсулу','До 32 файлов и 5 МБ суммарно. Данные обрабатываются на этом устройстве.',`<button class="button" id="demo-create">Загрузить демо-набор ↗</button>`)+`
<form id="create-form" novalidate><div class="panel"><div class="panel-heading"><h2><span class="step">01</span> Контекст передачи</h2><span class="badge">ЗАПОЛНЯЕТ АВТОР</span></div><div class="grid2"><div class="field"><label for="title">Название капсулы *</label><input id="title" maxlength="160" placeholder="Например, данные для передачи проекта" value="${esc(draft.title)}" required></div><div class="field"><label for="owner">Автор / организация *</label><input id="owner" maxlength="200" placeholder="Указанное вами имя" value="${esc(draft.owner)}" required><small>Самостоятельное заявление, личность не удостоверяется</small></div></div><div class="field"><label for="description">Описание и границы передачи *</label><textarea id="description" maxlength="2000" placeholder="Что внутри и для какой задачи подготовлен пакет?" required>${esc(draft.description)}</textarea></div><div class="field"><label for="license">Условия использования *</label><textarea id="license" maxlength="2000" placeholder="Разрешения, ограничения и ссылка на документ о правах" required>${esc(draft.license)}</textarea><small>Текст автора не заменяет договор и не устанавливает наличие прав</small></div></div>
<div class="panel"><div class="panel-heading"><h2><span class="step">02</span> Файлы пакета</h2><span id="file-summary" class="top-note"></span></div><div class="dropzone" id="file-drop"><div class="upload-symbol">⇧</div><strong>Добавьте файлы или перетащите их сюда</strong><p>Имена файлов должны быть уникальными. Макс. 5 МБ суммарно.</p><input type="file" multiple id="files" aria-label="Добавить файлы в капсулу"></div><div id="file-list" class="file-list"></div></div>
<div class="panel"><div class="panel-heading"><h2><span class="step">03</span> Критерии проверки</h2><button class="button small" type="button" id="add-check">＋ Добавить критерий</button></div><p class="subtitle">Наличие и контрольная сумма каждого файла проверяются автоматически. Дополнительно можно проверить JSON-поле или колонки CSV.</p><div id="checks-list"></div><div class="note">Эти критерии проверяют структуру данных. Они не запускают приложения и не доказывают восстановимость произвольного программного стека.</div></div>
<div id="form-error" class="note error" role="alert" hidden></div><div class="actions"><button class="button primary" type="submit" id="create-submit">Создать и проверить капсулу <span>↗</span></button><span class="top-note">Ключ подписи создаётся для этого пакета и не сохраняется.</span></div></form>`;
for(const k of ['title','description','owner','license'])$('#'+k).addEventListener('input',e=>draft[k]=e.target.value);
$('#demo-create').onclick=demo;$('#files').onchange=e=>addFiles(e.target.files);const drop=$('#file-drop');for(const event of ['dragover','dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.toggle('drag',event==='dragover');if(event==='drop')addFiles(e.dataTransfer.files)});
$('#add-check').onclick=()=>{captureChecks();draft.checks.push({type:'json',file:draft.files[0]?.name||'',path:'',expected:'true'});renderChecks()};$('#create-form').onsubmit=createSubmit;renderFiles();renderChecks()}
function renderFiles(){const list=$('#file-list');if(!list)return;let total=draft.files.reduce((s,f)=>s+base64ToBytes(f.dataBase64).length,0);$('#file-summary').textContent=`${draft.files.length} / 32 · ${fmtBytes(total)} / 5 МБ`;list.innerHTML=draft.files.map((f,i)=>`<div class="file-row"><span>▤</span><span class="file-name">${esc(f.name)}</span><small>${fmtBytes(base64ToBytes(f.dataBase64).length)}</small><button class="icon-btn remove-file" type="button" data-index="${i}" aria-label="Удалить файл ${esc(f.name)}">×</button></div>`).join('');list.querySelectorAll('.remove-file').forEach(b=>b.onclick=()=>{captureChecks();const f=draft.files.splice(Number(b.dataset.index),1)[0];draft.checks=draft.checks.filter(c=>c.file!==f.name);renderFiles();renderChecks()})}
async function addFiles(fileList){if(busy)return;try{const added=[...fileList];if(draft.files.length+added.length>32)throw Error('Можно добавить не более 32 файлов');const names=new Set(draft.files.map(f=>f.name.toLowerCase()));let total=draft.files.reduce((s,f)=>s+base64ToBytes(f.dataBase64).length,0);for(const f of added){if(names.has(f.name.toLowerCase()))throw Error('Повторяющееся имя: '+f.name);names.add(f.name.toLowerCase());total+=f.size}if(total>LIMITS.binaryBytes)throw Error('Общий объём файлов не должен превышать 5 МБ');setBusy(true);const result=[];for(const f of added)result.push({name:f.name,mime:f.type||'application/octet-stream',dataBase64:bytesToBase64(new Uint8Array(await f.arrayBuffer()))});captureChecks();draft.files.push(...result);renderFiles();renderChecks();toast(`Добавлено файлов: ${added.length}`)}catch(e){showError(failText(e))}finally{setBusy(false);if($('#files'))$('#files').value=''}}
function captureChecks(){const rows=app.querySelectorAll('.check-row');if(!rows.length)return;draft.checks=[...rows].map(row=>{const type=row.dataset.type;return type==='csv'?{type,file:row.querySelector('[data-key=file]').value,columns:row.querySelector('[data-key=columns]').value}:{type,file:row.querySelector('[data-key=file]').value,path:row.querySelector('[data-key=path]').value,expected:row.querySelector('[data-key=expected]').value}})}
function renderChecks(){const list=$('#checks-list');if(!list)return;if(!draft.checks.length){list.innerHTML='<p class="check-meta" >Дополнительные критерии не заданы. Все файлы будут проверены по контрольным суммам.</p>';return}list.innerHTML=draft.checks.map((c,i)=>`<div class="check-row" data-index="${i}" data-type="${c.type}"><div class="field"><label>Тип критерия</label><select aria-label="Тип критерия ${i+1}" data-key="type"><option value="json" ${c.type==='json'?'selected':''}>Поле JSON</option><option value="csv" ${c.type==='csv'?'selected':''}>Колонки CSV</option></select></div><div class="field"><label>Файл</label><select aria-label="Файл критерия ${i+1}" data-key="file">${draft.files.map(f=>`<option ${c.file===f.name?'selected':''} value="${esc(f.name)}">${esc(f.name)}</option>`).join('')}</select></div>${c.type==='csv'?`<div class="field"><label>Колонки через запятую</label><input aria-label="Обязательные колонки ${i+1}" data-key="columns" placeholder="id,name" value="${esc(c.columns)}"></div><div></div>`:`<div class="field"><label>Путь к полю</label><input aria-label="Путь JSON ${i+1}" data-key="path" placeholder="status.ready" value="${esc(c.path)}"></div><div class="field"><label>Значение в JSON</label><input aria-label="Ожидаемое значение ${i+1}" data-key="expected" placeholder='true или "готово"' value="${esc(c.expected)}"></div>`}<button class="icon-btn remove-check" type="button" aria-label="Удалить критерий ${i+1}">×</button></div>`).join('');list.querySelectorAll('[data-key=type]').forEach(s=>s.onchange=()=>{captureChecks();const i=Number(s.closest('.check-row').dataset.index);const file=s.closest('.check-row').querySelector('[data-key=file]').value;draft.checks[i]=s.value==='csv'?{type:'csv',file,columns:''}:{type:'json',file,path:'',expected:'true'};renderChecks()});list.querySelectorAll('.remove-check').forEach(b=>b.onclick=()=>{captureChecks();draft.checks.splice(Number(b.closest('.check-row').dataset.index),1);renderChecks()})}
async function createSubmit(e){e.preventDefault();if(busy)return;try{$('#form-error').hidden=true;captureChecks();for(const k of ['title','description','owner','license'])draft[k]=$('#'+k).value.trim();if(['title','description','owner','license'].some(k=>!draft[k]))throw Error('Заполните название, автора, описание и условия использования');if(!draft.files.length)throw Error('Добавьте хотя бы один файл');if(draft.files.length+draft.checks.length>64)throw Error('В сумме допускается не более 64 критериев, включая файлы');setBusy(true);const checks=draft.files.map(f=>({type:'file',file:f.name}));for(const c of draft.checks){if(c.type==='csv'){const columns=c.columns.split(',').map(x=>x.trim()).filter(Boolean);if(!columns.length)throw Error('Укажите обязательные колонки CSV');checks.push({type:'csv',file:c.file,columns})}else{let expected;try{expected=JSON.parse(c.expected)}catch{throw Error('Ожидаемое значение должно быть JSON: например true, 42 или "готово"')}checks.push({type:'json',file:c.file,path:c.path,expected})}}current=await createCapsule({...draft,checks});report=await verifyCapsule(current);if(!report.valid)throw Error(report.errors.join('; '));pendingEncrypted=null;setRoute('verify');toast('Капсула создана. Скачайте пакет и сохраните fingerprint отдельно.')}catch(e){showError(failText(e))}finally{setBusy(false)}}
function verifyPage(){app.innerHTML=pageTitle('Проверить капсулу','Загрузите пакет, полученный от отправителя. Проверка выполняется заново на вашем устройстве.',`<a class="button" href="./offline-verifier.html" download>Автономный проверяющий ↗</a>`)+`
<div class="panel"><div class="panel-heading"><h2>Откройте файл капсулы</h2><span class="badge">ДО 12 МБ</span></div><div class="dropzone" id="verify-drop"><div class="upload-symbol">◈</div><strong>Файл .continuum.json</strong><p>Обычный или зашифрованный пакет. Ничего не отправляется на сервер.</p><input type="file" id="verify-file" accept=".json,application/json" aria-label="Выбрать капсулу для проверки"></div><div class="grid2 spaced"><div class="field"><label for="fingerprint">Доверенный fingerprint отправителя, необязательно</label><input id="fingerprint" placeholder="64 символа SHA-256" maxlength="64" autocomplete="off"><small>Получите его от отправителя по независимому каналу</small></div><div class="field"><label for="decrypt-password">Пароль зашифрованного пакета</label><input type="password" id="decrypt-password" autocomplete="off" placeholder="Только для зашифрованных капсул"><small>Не передавайте пароль вместе с файлом</small></div></div><div class="actions"><button class="button primary" id="verify-again" ${!current&&!pendingEncrypted?'disabled':''}>${pendingEncrypted?'Расшифровать и проверить':'Повторить проверку'}</button><button class="button ghost" id="clear-verify">Очистить</button></div><details class="spaced"><summary class="top-note">Вставить содержимое пакета вручную</summary><div class="field spaced"><label for="capsule-text">JSON капсулы</label><textarea id="capsule-text" spellcheck="false" placeholder="Вставьте содержимое .continuum.json"></textarea></div><button class="button small" id="verify-text">Проверить текст</button></details><div id="verify-error" class="note error" role="alert" hidden></div></div><div id="verification-result"></div>`;
$('#verify-file').onchange=async e=>{const f=e.target.files[0];if(f)await loadFile(f)};const drop=$('#verify-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=async e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files[0])await loadFile(e.dataTransfer.files[0])};$('#verify-text').onclick=()=>loadText($('#capsule-text').value);$('#verify-again').onclick=reverify;$('#fingerprint').oninput=()=>{resetVerification();const area=$('#verification-result');area.innerHTML='<div class="note warning">Fingerprint изменён. Повторите проверку.</div>'};$('#capsule-text').oninput=()=>resetVerification(true);$('#clear-verify').onclick=()=>{current=null;report=null;pendingEncrypted=null;verifyPage()};if(report)renderReport()}
function resetVerification(clear=false){report=null;if(clear){current=null;pendingEncrypted=null}const area=$('#verification-result');if(area)area.replaceChildren();const again=$('#verify-again');if(again)again.disabled=!current&&!pendingEncrypted}
async function loadFile(file){if(busy)return;resetVerification(true);try{if(file.size>12*1024*1024)throw Error('Файл капсулы превышает 12 МБ');await loadText(await file.text())}catch(e){showError(failText(e),'#verify-error')}}
async function loadText(text){if(busy)return;resetVerification(true);try{$('#verify-error').hidden=true;if(new TextEncoder().encode(text).length>12*1024*1024)throw Error('Пакет превышает 12 МБ');const parsed=JSON.parse(text);current=null;report=null;$('#verification-result').innerHTML='';if(isEncrypted(parsed)){pendingEncrypted=parsed;$('#verify-again').disabled=false;$('#verify-again').textContent='Расшифровать и проверить';if(!$('#decrypt-password').value){toast('Введите пароль, затем нажмите «Расшифровать и проверить».');$('#decrypt-password').focus();return}}else{pendingEncrypted=null;current=parseCapsuleJSON(text)}await reverify()}catch(e){showError(failText(e),'#verify-error');$('#verify-again').disabled=!current&&!pendingEncrypted}}
async function reverify(){if(busy)return;resetVerification();try{$('#verify-error').hidden=true;setBusy(true);if(pendingEncrypted){const raw=await decryptCapsule(pendingEncrypted,$('#decrypt-password').value);current=parseCapsuleJSON(raw);pendingEncrypted=null;$('#decrypt-password').value=''}if(!current)throw Error('Сначала выберите капсулу');const pin=$('#fingerprint').value.trim();if(pin&&!/^[a-f0-9]{64}$/i.test(pin))throw Error('Fingerprint должен содержать ровно 64 шестнадцатеричных символа');report=await verifyCapsule(current,pin?{expectedFingerprint:pin.toLowerCase()}:{});$('#verify-again').textContent='Повторить проверку';renderReport()}catch(e){showError(failText(e),'#verify-error')}finally{setBusy(false);if($('#verify-again'))$('#verify-again').disabled=!current&&!pendingEncrypted}}
function renderReport(){const r=report,m=current?.manifest||{},valid=!!r.valid;$('#verification-result').innerHTML=`<div class="panel"><div class="result-heading"><div class="result-symbol ${valid?'':'failed'}">${valid?'✓':'!'}</div><div><h2>${valid?'Целостность и критерии подтверждены':'Пакет не прошёл проверку'}</h2><p>${valid?'Проверены подпись, содержимое и заявленные критерии.':'Не используйте содержимое до выяснения причины.'}</p></div></div><div class="note ${r.trustedKeyMatch===true?'success':r.trustedKeyMatch===false?'error':'warning'}">${r.trustedKeyMatch===true?'Fingerprint совпал с указанным вами доверенным значением. Это не заменяет проверку личности и прав.':r.trustedKeyMatch===false?'Fingerprint не совпал с доверенным значением. Ключ отправителя не подтверждён.':'Ключ не сверён с отправителем. Подпись относится к встроенному ключу; личность владельца не удостоверена.'}</div><dl class="detail-list"><dt>Название</dt><dd>${esc(m.title)}</dd><dt>Указанный автор</dt><dd>${esc(m.owner)}</dd><dt>Создано по данным автора</dt><dd>${esc(m.createdAt)}</dd><dt>ID капсулы</dt><dd class="mono">${esc(r.capsuleId)}</dd><dt>Fingerprint ключа</dt><dd class="mono">${esc(r.fingerprint)} <button class="button small" id="copy-fingerprint">Копировать</button></dd><dt>Условия использования</dt><dd>${esc(m.license)}</dd><dt>Описание</dt><dd>${esc(m.description)}</dd></dl><div class="section-head"><h2>Результаты проверки</h2><span class="badge ${valid?'':'fail'}">${r.checks?.filter(c=>c.passed).length||0} / ${r.checks?.length||0}</span></div><div class="check-result"><span>Подпись пакета</span><span class="badge ${r.signatureValid?'':'fail'}">${r.signatureValid?'ВЕРНА':'ОШИБКА'}</span></div><div class="check-result"><span>Состав и контрольные суммы файлов</span><span class="badge ${r.filesValid?'':'fail'}">${r.filesValid?'СОВПАЛИ':'ОШИБКА'}</span></div>${(r.checks||[]).map(c=>`<div class="check-result"><span>${esc(c.file)}<small>${esc(c.type==='json'?'Поле JSON':c.type==='csv'?'Колонки CSV':'Наличие файла')} · ${esc(c.detail)}</small></span><span class="badge ${c.passed?'':'fail'}">${c.passed?'ПРОЙДЕНО':'ОШИБКА'}</span></div>`).join('')}${r.errors?.length?`<div class="note error">${r.errors.map(esc).join('<br>')}</div>`:''}
${valid?`<hr class="divider"><div class="grid2"><div class="field"><label for="export-password">Пароль экспорта, необязательно</label><input type="password" id="export-password" autocomplete="new-password" minlength="12" placeholder="От 12 символов для шифрования"><small>Без пароля содержимое экспортируется открыто. Утраченный пароль восстановить нельзя.</small></div><div class="field"><label>Сохранение</label><small>Файл переносим между устройствами. В хранилище этого браузера содержимое сохраняется без шифрования.</small></div></div><div class="actions"><button class="button primary" id="export-capsule">Скачать капсулу ↓</button><button class="button" id="save-vault">Сохранить в браузере</button><button class="button ghost" id="export-report">Скачать отчёт</button></div><div class="section-head"><h2>Файлы внутри</h2><small>СКАЧИВАЙТЕ ТОЛЬКО ИЗ ДОВЕРЕННЫХ ИСТОЧНИКОВ</small></div>${(m.files||[]).map((f,i)=>`<div class="file-row"><span>▤</span><span class="file-name">${esc(f.name)}</span><small>${fmtBytes(f.size)}</small><button class="button small extract-file" data-index="${i}">Скачать файл</button></div>`).join('')}`:''}</div>`;
$('#copy-fingerprint').onclick=async()=>{try{await navigator.clipboard.writeText(r.fingerprint);toast('Fingerprint скопирован')}catch{toast('Копирование недоступно — выделите fingerprint вручную')}};
if(!valid)return;$('#export-capsule').onclick=exportCurrent;$('#save-vault').onclick=async()=>{try{await vault('save',{id:r.capsuleId,capsule:current,savedAt:new Date().toISOString()});await countVault();toast('Капсула сохранена в этом браузере. Экспортируйте резервную копию.')}catch(e){toast(failText(e))}};$('#export-report').onclick=()=>download(JSON.stringify({format:'continuum/report-1',checkedAt:new Date().toISOString(),...r},null,2),'continuum-report.json');app.querySelectorAll('.extract-file').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.index),file=current.files[i];download(base64ToBytes(file.dataBase64),String(i+1).padStart(2,'0')+'-'+file.name.replaceAll('/','__'),'application/octet-stream')})}
async function exportCurrent(){if(busy||!current||!report?.valid)return;try{setBusy(true);const password=$('#export-password')?.value||'';const envelope=password?await encryptCapsule(current,password):current;download(JSON.stringify(envelope,null,2),`continuum-${report.capsuleId.slice(0,12)}.continuum.json`);if($('#export-password'))$('#export-password').value='';toast(password?'Зашифрованный пакет скачан. Сохраните пароль отдельно.':'Пакет скачан. Содержимое не зашифровано.')}catch(e){toast(failText(e))}finally{setBusy(false)}}
async function vaultPage(){app.innerHTML=pageTitle('Локальное хранилище','Сохранённые капсулы доступны только в этом браузере и на этом устройстве.',`<a class="button primary" href="#create">Создать капсулу ↗</a>`)+`<div class="note warning">Хранилище не зашифровано и не синхронизируется между устройствами. Очистка данных браузера удалит капсулы. Скачивайте резервные копии; для конфиденциальных материалов используйте экспорт с паролем.</div><div id="vault-content" class="loading">Загрузка…</div>`;try{const rows=await vault('list');const items=rows.filter(item=>item&&typeof item.id==='string'&&/^[a-f0-9]{64}$/.test(item.id)&&typeof item.savedAt==='string'&&Number.isFinite(Date.parse(item.savedAt))&&item.capsule&&typeof item.capsule.manifest?.title==='string'&&typeof item.capsule.manifest?.description==='string'&&Array.isArray(item.capsule.files)).sort((a,b)=>b.savedAt.localeCompare(a.savedAt));const corrupt=rows.length-items.length;if(route()!=='vault')return;const el=$('#vault-content');el.className='vault-grid';if(!items.length){el.className='panel';el.innerHTML='<div class="empty"><div class="empty-icon">▦</div><h3>Здесь появятся ваши капсулы</h3><p>Создайте пакет и нажмите «Сохранить в браузере» после проверки.</p><a class="button" href="#create">Создать первую капсулу ↗</a></div>';return}if(corrupt)toast('Повреждённых локальных записей: '+corrupt+'. Исправные капсулы доступны.');el.innerHTML=items.map((item,i)=>`<article class="vault-card"><span class="badge">СОХРАНЕНО НА УСТРОЙСТВЕ</span><h3>${esc(item.capsule.manifest.title)}</h3><p>${esc(item.capsule.manifest.description.slice(0,150))}</p><div class="mono">${esc(item.id.slice(0,24))}…</div><p>${item.capsule.files.length} файлов · ${esc(new Date(item.savedAt).toLocaleDateString('ru-RU'))}</p><div class="actions"><button class="button small primary open-vault" data-index="${i}">Открыть и проверить ↗</button><button class="button small danger remove-vault" data-index="${i}">Удалить</button></div></article>`).join('');el.querySelectorAll('.open-vault').forEach(b=>b.onclick=async()=>{try{current=items[Number(b.dataset.index)].capsule;report=await verifyCapsule(current);pendingEncrypted=null;setRoute('verify')}catch(e){toast(failText(e))}});el.querySelectorAll('.remove-vault').forEach(b=>b.onclick=async()=>{const item=items[Number(b.dataset.index)];if(!confirm('Удалить эту локальную копию капсулы? Скачанные файлы останутся.'))return;try{await vault('delete',item.id);await countVault();vaultPage();toast('Локальная копия удалена')}catch(e){toast(failText(e))}})}catch(e){const el=$('#vault-content');if(el){el.className='note error';el.textContent=failText(e)}}}
function guidePage(){app.innerHTML=pageTitle('Передача, которую можно проверить.','Что представляет собой капсула, какие гарантии даёт проверка и где проходят её границы.')+`<div class="guide"><section class="panel"><h2>Что создаёт Continuum</h2><p>Переносимый пакет файлов с описанием, условиями использования и явными критериями приёмки. Получатель может пересчитать контрольные суммы, проверить цифровую подпись и повторить проверки JSON и CSV на своём устройстве.</p><p>Практическая задача — передача данных и контекста между владельцами процесса. Потенциальный актив — полезные материалы и право их использовать, если оно действительно есть. Файл капсулы сам по себе не создаёт исключительные права, дефицит или денежную стоимость.</p><h3>Сценарий передачи</h3><ol><li>Автор собирает файлы и задаёт критерии. Система создаёт для этого пакета одноразовый ключ и подпись.</li><li>Автор скачивает капсулу и отдельно передаёт получателю fingerprint ключа по проверенному каналу.</li><li>Получатель открывает капсулу, вводит доверенный fingerprint и выполняет проверку заново.</li><li>Стороны отдельно проверяют договор, личность, полноту данных и возможность выполнить реальную задачу.</li></ol><h3>Что проверяется</h3><ul><li>Точное соответствие содержимого подписанному манифесту: размеры и SHA-256 всех файлов.</li><li>Подпись ECDSA P-256 / SHA-256 встроенным публичным ключом.</li><li>Наличие файлов, равенство заданного поля JSON и наличие колонок CSV.</li><li>Соответствие fingerprint значению, которое ввёл получатель.</li></ul><h3>Что не подтверждается</h3><p>Личность автора, время создания, законность передачи, достоверность данных, отсутствие вредоносных файлов, полнота проекта, восстановление произвольного ПО, рыночная цена и будущая доходность. Имя автора и условия — текстовые заявления автора.</p><p>Подписывающий ключ не сохраняется. Каждая капсула имеет собственный ключ; это не долговременная цифровая личность. Отзыв и обновление старой подписи не предусмотрены. Изменения оформляются новой капсулой.</p></section><section class="panel"><h2>Конфиденциальность и хранение</h2><p>Приложение не отправляет содержимое файлов на сервер и не использует внешнюю аналитику. Сервер предоставляет код приложения и может вести обычные журналы доступа, не содержащие содержимое капсул.</p><p>Созданный пакет хранится в памяти до явного сохранения. Локальное хранилище использует IndexedDB без шифрования; оно доступно пользователю этого браузера. Это не резервная копия и не облачная синхронизация.</p><p>При экспорте можно указать пароль от 12 символов. Содержимое шифруется AES-256-GCM с PBKDF2-SHA256, случайной солью и 210 000 итераций. Пароль не сохраняется. Шифрование не защищает от слабого пароля, заражённого устройства или изменённого кода приложения.</p><p>Независимая проверка возможна через <a href="./offline-verifier.html" download>автономный HTML-проверяющий</a>. Скачайте его заранее из доверенного источника. Исходники и формат открыты для изучения; внешнего аудита безопасности пока не было.</p></section><section class="panel"><h2>Границы новизны и бизнес-гипотеза</h2><p>Комбинация проверяемого пакета с явными критериями приёмки — продуктовая гипотеза. Принципы уже встречаются в <a href="https://www.rfc-editor.org/rfc/rfc8493.html" target="_blank" rel="noopener noreferrer">BagIt</a>, <a href="https://www.researchobject.org/ro-crate/specification/1.2/introduction.html" target="_blank" rel="noopener noreferrer">RO-Crate</a> и <a href="https://in-toto.io/docs/getting-started/" target="_blank" rel="noopener noreferrer">in-toto</a>. Continuum использует собственный формат и не заявляет совместимость с этими стандартами.</p><p>Мировая новизна и патентоспособность не установлены. Наличие программы не подтверждает спрос. Проверка коммерческой гипотезы — пилот передачи данных у реального клиента с измерением времени, ошибок и затрат на приёмку. Продажи и платёжная система в этой версии не реализованы.</p><h3>Технические пределы</h3><p>До 32 файлов, 5 МБ исходных данных и 64 критериев. Канонизация JSON — внутренний формат версии 1, не RFC 8785. CSV — разделитель-запятая и строка заголовков. JSON-пути разделяются точкой. Неизвестные поля и неподдерживаемые форматы отклоняются.</p></section></div>`}
function render(){if(busy)return;const r=route();app.dataset.route=r;$('#page-label').textContent=labels[r];document.querySelectorAll('[data-route]').forEach(el=>{const active=el.dataset.route===r;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});if(r==='home')home();else if(r==='create')createPage();else if(r==='verify')verifyPage();else if(r==='vault')vaultPage();else guidePage();window.scrollTo(0,0)}
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue=''}});if(!crypto.subtle){app.innerHTML='<div class="note error">Для работы нужен современный браузер с WebCrypto и HTTPS.</div>'}else{render();countVault()}
